/**
 * Old <-> new company slug equivalence (src/data/slug-renames.json, generated by
 * scripts/weekly/slug_renames.py). Denylist, exclusion and hold keys keep their
 * written form; lookups go through slugEquivalents() so a key matches the company
 * both before and after a catalog rebuild moves it to its canonical slug.
 */
import slugRenames from "../data/slug-renames.json" with { type: "json" };

/** Same normalization as scripts/weekly/slug_aliases.py: trim + lowercase. */
export function normSlug(slug: string): string {
  return slug.trim().toLowerCase();
}

/** old -> new. A Map, so keys such as "constructor" or "__proto__" never hit the prototype. */
export const SLUG_RENAMES: ReadonlyMap<string, string> = new Map(
  Object.entries(slugRenames.renames).map(([o, n]) => [normSlug(o), normSlug(n)]),
);
/** new -> old. */
export const SLUG_RENAMED_FROM: ReadonlyMap<string, string> = new Map([...SLUG_RENAMES].map(([o, n]) => [n, o]));

export function slugEquivalents(slug: string): string[] {
  const s = normSlug(slug);
  if (!s) return [];
  const out = [s];
  for (const other of [SLUG_RENAMES.get(s), SLUG_RENAMED_FROM.get(s)]) if (other && !out.includes(other)) out.push(other);
  return out;
}

/** True when any equivalent of `slug` is in `keys`. */
export function hasSlugKey(keys: { has(k: string): boolean }, slug: string): boolean {
  return slugEquivalents(slug).some((k) => keys.has(k));
}

/** Set with every key plus its rename equivalent, so `.has()` matches both forms. */
export function expandSlugs(keys: Iterable<string>): Set<string> {
  const out = new Set<string>();
  for (const k of keys) for (const e of slugEquivalents(k)) out.add(e);
  return out;
}
